\label{def:assignment}

For each patient $m \ge 1$, the \emph{assignment vector}
$X_m = (X_{m,1}, \dots, X_{m,K})$ takes values in $\{0,1\}^K$ and satisfies
$\sum_{k=1}^K X_{m,k} = 1$. The event $\{X_{m,k} = 1\}$ means that patient $m$ is
assigned to arm $k$.

\label{lem:counts_sum}


For all $n \ge 1$, $\sum_{k=1}^K N_{n,k} = n$, and hence
$\sum_{k=1}^K \frac{N_{n,k}}{n} = 1$.

\label{def:condA}

Condition~\textbf{A} holds if for every arm $k \in [K]$ the response satisfies
$\mathbb{E}|\xi_{1,k}|^2 < \infty$ (equivalently $V_k < \infty$).

\label{def:condB}

Condition~\textbf{B} holds if the domain $\mathcal{H}$ is open and contains
$I_1 \times \dots \times I_K$, and moreover
\begin{itemize}
  \item $\rho$ is twice differentiable on $\mathcal{H}$;
  \item for every $z \in I_1 \times \dots \times I_K$, $\rho(z) \in (0,1)^K$.
\end{itemize}
In particular the target allocation $v = \rho(\Theta)$ is non-sparse:
$v_k > 0$ for all $k$.

\label{def:sparse}

A target function $\rho$ is \emph{sparse at $\Theta$} if some component of
$v = \rho(\Theta)$ is zero.

\label{def:op_Op}

Let $(a_n)_{n\ge1}$ be positive reals and $(X_n)_{n\ge1}$ random variables.
\begin{itemize}
  \item $X_n = o_p(a_n)$ if for all $\varepsilon > 0$,
        $\mathbb{P}\!\big(|X_n|/a_n > \varepsilon\big) \to 0$.
  \item $X_n = O_p(a_n)$ if for all $\varepsilon > 0$ there is $M > 0$ with
        $\limsup_n \mathbb{P}\!\big(|X_n|/a_n > M\big) \le \varepsilon$
        (boundedness in probability of $X_n / a_n$).
\end{itemize}

\label{def:aRTS}

Let $K \ge 2$, $\alpha \in [0,1)$ and $m_0 \in \mathbb{N}$ (a burn-in parameter).
A RAR procedure is an \emph{$\alpha$-Rebalancing Targeting Strategy} ($\alpha\text{RTS}$)
if its allocation probabilities $p_{m+1} \in \Delta_K$ satisfy, for all
$m \ge K m_0$, the \emph{throttling condition}
\begin{equation}\label{eq:throttle}
  \forall k \in [K], \quad
  \frac{N_{m,k}}{m} > \hat{\rho}_{m,k}
  \ \Longrightarrow\
  p_{m+1,k} \le \alpha\, \hat{\rho}_{m,k}.
\end{equation}
In words: whenever arm $k$ is currently over-sampled relative to its estimated
target, the probability of selecting it next is throttled down to at most
$\alpha \hat{\rho}_{m,k}$.

\begin{equation}\label{eq:throttle}
  \forall k \in [K], \quad
  \frac{N_{m,k}}{m} > \hat{\rho}_{m,k}
  \ \Longrightarrow\
  p_{m+1,k} \le \alpha\, \hat{\rho}_{m,k}.
\end{equation}

\label{lem:distance_simplex}


For all $m \ge K m_0$, the vector $p_{m+1}$ of Definition~\ref{def:distance_design}
lies in $\Delta_K$.

\label{lem:distance_isARTS}


The distance-based design satisfies the throttling condition \eqref{eq:throttle},
hence belongs to the $\alpha\text{RTS}$ family.

\label{lem:erade2025_simplex}


For all $m \ge K m_0$, the vector $p_{m+1}$ of Definition~\ref{def:erade2025}
lies in $\Delta_K$.

\label{lem:erade2025_isARTS}


The ERADE 2025 design satisfies \eqref{eq:throttle}, hence belongs to the
$\alpha\text{RTS}$ family.

\label{lem:d_tracking_isARTS}


For every $\alpha \in [0,1)$, the Interpolated D-Tracking rule satisfies
\eqref{eq:throttle}, hence belongs to the $\alpha\text{RTS}$ family.

\label{lem:M_martingale}


For each $k \in [K]$, $(M_{n,k})_{n\ge0}$ is an $(\mathcal{F}_n)$-martingale with
$M_{0,k}=0$ and bounded increments $|\Delta M_{m,k}| \le 1$.

\label{lem:count_decomp}


For all $n\ge1$ and $k\in[K]$,
$\displaystyle N_{n,k} = \sum_{m=1}^n p_{m,k} + M_{n,k}$.

\label{lem:Q_second_moment}


Under Condition~\textbf{A}, for each $k \in [K]$,
$\mathbb{E}[Q_{n,k}^2] = V_k\,\mathbb{E}[N_{n,k}]$.

\label{lem:Q_Op}


For each $k \in [K]$, if the responses are square-integrable (Condition~\textbf{A}), then
$Q_{n,k} = O_p(\sqrt n)$.

\label{lem:hitting_sign}


For $m > \ell_{n,k}$ (and $m \le n$), $\frac{N_{m,k}}{m} > \hat{\rho}_{m,k}$;
in particular, for an $\alpha\text{RTS}$ design with $m \ge Km_0$, $p_{m+1,k} \le \alpha\hat{\rho}_{m,k}$.

\label{lem:expectation_to_O}


Let $(u_n)_{n\ge1}$ be positive reals and $(X_n)_{n\ge1}$ real random variables.
If there is $C > 0$ with $\mathbb{E}|X_n| \le C u_n$ for all $n$, then $X_n = O_p(u_n)$.

\label{lem:sq_expectation_to_O}


Let $(u_n)_{n\ge1}$ be positive reals and $(X_n)_{n\ge1}$ real random variables.
If there is $C \ge 0$ with $\mathbb{E}[X_n^2] \le C u_n^2$ for all $n$, then $X_n = O_p(u_n)$.

\label{lem:mart_bdd_incr_Op}


Let $M$ be a martingale with $M_0 = 0$ whose increments are bounded,
$|\Delta M_{n+1}| \le c$ a.s.\ for all $n$. Then $M_n = O_p(\sqrt n)$.

\label{def:generic_cond}

Let $(\ell_{n,k})_{n\ge1, k\in[K]}$ be integer-valued random variables. We say
that a RAR procedure \emph{satisfies the generic conditions with $\ell$} if:
\begin{enumerate}
  \item[(i)] for all $k$, $(\ell_{n,k})_n$ is non-decreasing and $\ell_{n,k}\le n$;
  \item[(ii)] for all $k,n$,
        \begin{equation}\label{eq:generic_ineq}
          N_{n,k} - n\hat{\rho}_{n,k}
          \le 1 + N_{\ell_{n,k},k} - \ell_{n,k}\hat{\rho}_{\ell_{n,k},k}
             + U_{n,k} - U_{\ell_{n,k},k};
        \end{equation}
  \item[(iii)] for all $k,n$,
        \begin{equation}\label{eq:generic_small}
          N_{\ell_{n,k},k} - \ell_{n,k}\hat{\rho}_{\ell_{n,k},k} = o(\sqrt n)
          \quad\text{a.s.}
        \end{equation}
\end{enumerate}

