\label{lem:respMart_div_count_slln}


For each arm $k$, on the event $\{N_{n,k}\to\infty\}$ the bracket-normalized response
martingale vanishes: $\dfrac{Q_{n,k}}{N_{n,k}}\to 0$ a.s.

\label{lem:theta_limit_infinite}


For each arm $k$, on the event $\{N_{n,k}\to\infty\}$ the estimator converges a.s.\ to the arm
mean: $\hat\theta_{n,k}\to\theta_k$.

\label{lem:theta_limit_finite}


For each arm $k$ and each realization, if $N_{n,k}\not\to\infty$ then $\hat\theta_{n,k}$ is
eventually constant, and in particular converges.

\label{lem:theta_converges}


For each arm $k$, the estimator $\hat\theta_{n,k}$ converges a.s.: to $\theta_k$ on
$\{N_{n,k}\to\infty\}$ and to an eventually-attained value on $\{\sup_n N_{n,k}<\infty\}$.

$(M_{n,k})$ is a martingale with bounded increments $|\Delta M_{m,k}|\le1$, so its
increments have summable normalized variances $\sum_m \frac{\mathbb{V}\mathrm{ar}(\Delta M_{m,k})}{m^2}<\infty$;
the strong law of large numbers for martingales gives $M_{n,k}/n \to 0$ a.s.

\label{lem:neg_part_vanishes}


Under the same hypotheses, for each $k$,
$\big(\hat{\rho}_{n,k} - \frac{N_{n,k}}{n}\big)^+ \to 0$ a.s.

\label{lem:match}


Under the same hypotheses, for each $k$,
$\frac{N_{n,k}}{n} - \hat{\rho}_{n,k} \to 0$ and
$\frac{N_{n,k}}{n} \to u_k \in (0,1)$ a.s. (The formalized statement \texttt{match\_proportion}
delivers $\frac{N_{n,k}}{n}\to u_k$ from the two vanishing positive parts and $\hat{\rho}_{n,k}\to
u_k$.)

\label{lem:theta_consistent}


Under the same hypotheses, $\hat{\Theta}_n \to \Theta$ a.s., and consequently
$\hat{\rho}_n \to v = \rho(\Theta)$ and $\frac{N_{n,k}}{n}\to v_k$ a.s.

\begin{align*}
  |N_{n,k} - n\hat{\rho}_{n,k}| &= o_p(\sqrt n), &
  |N_{n,k} - n\hat{\rho}_{n,k}| &= O(\sqrt{n\log\log n})\ \text{a.s.}, \\
  N_{n,k} - n v_k &= O(\sqrt{n\log\log n})\ \text{a.s.}
\end{align*}

\label{thm:normality}

Under the generic conditions and Conditions~\textbf{A}--\textbf{B}, as
$n\to\infty$:
\begin{enumerate}
  \item[(i)] for every $k$, $|N_{n,k}-n\hat{\rho}_{n,k}|=o_p(\sqrt n)$,
        $|N_{n,k}-n\hat{\rho}_{n,k}|=O(\sqrt{n\log\log n})$ a.s., and
        $N_{n,k}-nv_k=O(\sqrt{n\log\log n})$ a.s.;
  \item[(ii)] $\sqrt n(\hat{\Theta}_n-\Theta)\overset{\mathcal{D}}{\longrightarrow}\mathcal{N}(0,V)$ and
        \[
          \begin{pmatrix}\sqrt n(N_n/n - v)\\ \sqrt n(\hat{\rho}_n - v)\end{pmatrix}
          \overset{\mathcal{D}}{\longrightarrow} \mathcal{N}(0,\Omega).
        \]
\end{enumerate}

\label{def:exploration_schedule}

An \emph{exploration schedule} is a function $h : \mathbb{N} \to \mathbb{R}$ with
\begin{enumerate}
  \item[(i)] $\lim_{n\to\infty} h(n) = +\infty$;
  \item[(ii)] $h(n) = o(\sqrt n)$ as $n\to\infty$.
\end{enumerate}
(The Lean \texttt{AlphaRAR.IsExplorationSchedule} additionally records that $h$ is nondecreasing, a
harmless convenience satisfied by the paper's examples that gives $h(\ell)\le h(n)$ for $\ell\le n$.
It also \emph{weakens} (ii) to $h(n)=o(n)$: no result of the formalization uses $h(n)=o(\sqrt n)$
--- see Remark~\ref{rem:sparse_clt_fix} --- and the paper's condition survives only as the separate
predicate \texttt{AlphaRAR.IsSqrtSmall}, which nothing assumes.)

\label{ex:h_choice}
The D-Tracking choice $h(n) = (\sqrt n - K/2)^+$ of \cite{garivier2016optimal}
violates condition (ii). The choice $h(n) = (n^{1/3} - K/2)^+$ satisfies both
conditions and is used in the experiments.

\label{def:aRTSFE}


Fix $\alpha\in[0,1)$ and a schedule $h$. A RAR procedure is in the $\alpha\text{RTS-FE}$
family if its allocation probabilities obey:
\begin{align}
  \textbf{(Forced exploration)}\quad
    &\mathbf{U}_m\ne\emptyset \Rightarrow \forall a\in\mathbf{S}_m:\ p_{m+1,a}=\tfrac{1}{|\mathbf{S}_m|};
    \label{eq:fe_phase}\\
  \textbf{(Otherwise)}\quad
    &\mathbf{U}_m=\emptyset \Rightarrow p_{m+1}\ \text{satisfies the throttling condition \eqref{eq:throttle}.}
    \label{eq:fe_otherwise}
\end{align}
Like \texttt{AlphaRAR.IsARTS}, the Lean predicate \texttt{AlphaRAR.IsARTSFE} is stated on
\emph{histories}, so it is a property of the algorithm alone; \texttt{throttle\_of\_isARTSFE} and
\texttt{fe\_of\_isARTSFE} transport it to the process. It weakens \eqref{eq:fe_phase} to
$a\notin\mathbf{S}_m\Rightarrow p_{m+1,a}=0$: uniformity on $\mathbf{S}_m$ is never used, only that
no other arm can be drawn.

\begin{align}
  \textbf{(Forced exploration)}\quad
    &\mathbf{U}_m\ne\emptyset \Rightarrow \forall a\in\mathbf{S}_m:\ p_{m+1,a}=\tfrac{1}{|\mathbf{S}_m|};
    \label{eq:fe_phase}\\
  \textbf{(Otherwise)}\quad
    &\mathbf{U}_m=\emptyset \Rightarrow p_{m+1}\ \text{satisfies the throttling condition \eqref{eq:throttle}.}
    \label{eq:fe_otherwise}
\end{align}

\label{rem:d_tracking_fe}
The full D-Tracking algorithm of \cite{garivier2016optimal} is the $\alpha\text{RTS-FE}$
member with $\alpha=0$ (up to the choice of $h$).

\label{lem:hitting_fe_sign}


For an $\alpha\text{RTS-FE}$ design and $m$ with $\ell_{n,k}^{\mathrm{FE}} < m \le n$,
we have $\frac{N_{m,k}}{m} > \hat{\rho}_{m,k}$ and
$\big(\mathbf{U}_m=\emptyset\ \text{or}\ k\notin arg\,min_{j\in\mathbf{U}_m}N_{m,j}\big)$;
consequently $p_{m+1,k}\le\alpha\hat{\rho}_{m,k}$ (equal to $0$ during a forced
exploration step in which $k$ is not least-sampled).

\label{lem:preliminary_fe}


For any $\alpha\text{RTS-FE}$ design, the generic conditions
(Definition~\ref{def:generic_cond}) hold with $\ell_{n,k}^{\mathrm{FE}}$.

\label{thm:forced_valid}


Under Conditions~\textbf{A}--\textbf{B}, Theorem~\ref{thm:LLN} and
Theorem~\ref{thm:normality} hold for every design in the $\alpha\text{RTS-FE}$ family.

\label{lem:fe_no_starvation}


For any $\alpha\text{RTS-FE}$ design, $N_{n,k}\to\infty$ a.s.\ for every $k\in[K]$ (no
assumption on the target).

\label{lem:op_factor}

$X_n = o_p(a_n)$ if and only if $X_n/a_n = o_p(1)$, and $X_n = O_p(a_n)$ if and
